patch:
diff --git a/repro/no-lonely-if-19033.js b/repro/no-lonely-if-19033.js
new file mode 100644
index 0000000..4484fab
--- /dev/null
+++ b/repro/no-lonely-if-19033.js
@@ -0,0 +1,33 @@
+"use strict";
+// Repro for no-lonely-if unsafe autofix (eslint#19033).
+// Usage: node repro/no-lonely-if-19033.js [path-to-eslint-package]
+const path = require("node:path");
+const vm = require("node:vm");
+const eslintDir = process.argv[2] ? path.resolve(process.argv[2]) : path.join(__dirname, "..");
+const { Linter } = require(path.join(eslintDir, "lib/api"));
+const version = require(path.join(eslintDir, "package.json")).version;
+
+const code = `/* eslint no-lonely-if: "error" */
+if (true)
+	if (false) {}
+	else { if (false) {} }
+else throw Error('This \`else\` should have been unreachable!');
+`;
+
+const linter = new Linter({ configType: "flat" });
+const messages = linter.verify(code, [], "x.js");
+const { output, fixed } = linter.verifyAndFix(code, [], "x.js");
+
+function run(src) {
+    try { vm.runInNewContext(src, {}); return "ok"; } catch (e) { return `throws: ${e.message}`; }
+}
+
+console.log(`eslint ${version}`);
+console.log("messages:", messages.map(m => `${m.line}:${m.column} ${m.ruleId}: ${m.message}`));
+console.log("fixed:", fixed);
+console.log("--- output ---\n" + output);
+console.log("original runs:", run(code));
+console.log("fixed runs:   ", run(output));
+const bug = fixed && run(code) !== run(output);
+console.log(bug ? "BUG: autofix changed runtime behavior" : "no behavior change");
+process.exitCode = bug ? 1 : 0;
